begin;
create function pg_temp.assert_true(value boolean,label text) returns void language plpgsql as $$begin if value is not true then raise exception 'FAILED: %',label;end if;end$$;
create function pg_temp.reject(query text,code text default null) returns void language plpgsql as $$declare blocked boolean:=false;begin begin execute query;exception when others then if code is not null and SQLSTATE<>code then raise;end if;blocked:=true;end;if not blocked then raise exception 'Invalid operation succeeded: %',query;end if;end$$;
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000001';
select public.configure_pilot(true,'10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000001',true);
select set_config('op.session',public.create_class_session('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002',now()-interval '2 hours',now()-interval '1 hour','Pilot fixture')::text,true);
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000002';
select public.start_class_session(current_setting('op.session')::uuid);
select set_config('op.attempt',public.open_pilot_checkout(current_setting('op.session')::uuid,'mobile')::text,true);
select pg_temp.assert_true(public.open_pilot_checkout(current_setting('op.session')::uuid,'mobile')::text=current_setting('op.attempt'),'Refresh preserves first timer');
select public.record_pilot_error(current_setting('op.attempt')::uuid,'57000000-0000-0000-0000-000000000001');
select public.record_pilot_error(current_setting('op.attempt')::uuid,'57000000-0000-0000-0000-000000000001');
select set_config('op.data',(select jsonb_build_object('lesson_content','Pilot lesson','homework_assigned','Practice','records',jsonb_agg(jsonb_build_object('student_id',student_id,'attendance','present','homework_status',case when student_id='30000000-0000-0000-0000-000000000001' then 'missing' else 'done' end,'old_lesson_status','passed','quick_score',null,'needs_attention',false,'attention_reasons','[]'::jsonb,'teacher_note','private-marker'))) from public.session_student_records where session_id=current_setting('op.session')::uuid)::text,true);
select public.save_session_checkout(current_setting('op.session')::uuid,1,current_setting('op.data')::jsonb,true);
select set_config('op.record',(select id::text from public.session_student_records where session_id=current_setting('op.session')::uuid and student_id='30000000-0000-0000-0000-000000000001'),true);
select set_config('op.correction',public.request_correction(current_setting('op.session')::uuid,current_setting('op.record')::uuid,'homework_status','done','Wrong homework checkbox')::text,true);
select pg_temp.reject('select public.request_correction('''||current_setting('op.session')||''','''||current_setting('op.record')||''',''homework_status'',''done'',''Duplicate request retry'')','23505');
select pg_temp.reject('select public.review_correction('''||current_setting('op.correction')||''',true,''Teacher approves self'')','42501');
select pg_temp.reject('select public.generate_schedule(''00000000-0000-0000-0000-000000000001'',current_date,current_date+1)','42501');
select set_config('op.rejected',public.request_correction(current_setting('op.session')::uuid,current_setting('op.record')::uuid,'teacher_note','Rejected private note','Check a private note correction')::text,true);
select pg_temp.assert_true((select count(*)=0 from public.audit_events),'Teacher cannot read audit');
select pg_temp.reject('insert into public.audit_events(action,entity_type,entity_id) values(''fake'',''task'',''00000000-0000-0000-0000-000000000001'')','42501');
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000004';
select pg_temp.assert_true((select count(*)=0 from public.session_corrections),'CSKH cannot read correction values/reasons');
select pg_temp.reject('select private.corrected_value('''||current_setting('op.session')||''','''||current_setting('op.record')||''',''teacher_note'','''')','42501');
select pg_temp.reject('select public.mark_notification(id) from (select '''||current_setting('op.correction')||'''::uuid id) q','42501');
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000001';
select public.review_correction(current_setting('op.correction')::uuid,true,'Approved after review');
select pg_temp.assert_true((select homework_status='missing' from public.session_student_records where id=current_setting('op.record')::uuid),'Original completed record immutable');
select pg_temp.assert_true((select homework_status='done' from public.effective_session_records where id=current_setting('op.record')::uuid),'Approved effective record changed');
select pg_temp.assert_true((select status='cancelled' from public.tasks where student_id='30000000-0000-0000-0000-000000000001' and type='homework_followup'),'Wrong followup reconciled with audit');
select pg_temp.assert_true(public.student_pulse('30000000-0000-0000-0000-000000000001')->>'color'='green','Pulse uses amendments');
select set_config('op.audit',(select count(*)::text from public.audit_events),true);
select public.review_correction(current_setting('op.correction')::uuid,true,'Retry');
select pg_temp.assert_true((select count(*)::text=current_setting('op.audit') from public.audit_events),'Approval replay no duplicate audit');
select pg_temp.reject('select public.review_correction('''||current_setting('op.rejected')||''',false,'''')');
select public.review_correction(current_setting('op.rejected')::uuid,false,'Original note is correct');
select public.review_correction(current_setting('op.rejected')::uuid,false,'Retry rejection');
select pg_temp.assert_true((select status='rejected' and reviewed_by=auth.uid() and review_note='Original note is correct' from public.session_corrections where id=current_setting('op.rejected')::uuid),'Rejection and reviewer are persisted; retry does not overwrite reason');
select pg_temp.assert_true(private.corrected_value(current_setting('op.session')::uuid,current_setting('op.record')::uuid,'teacher_note','private-marker')='private-marker','Rejected correction never changes effective private note');
select pg_temp.assert_true((public.pilot_metrics()->>'sessions')::int=1 and (public.pilot_metrics()->>'save_errors')::int=1,'Pilot complete/error dedupe and aggregates');
select pg_temp.assert_true(not exists(select 1 from public.audit_events where metadata::text like '%private-marker%' or metadata::text like '%Wrong homework checkbox%'),'Audit metadata omits content/reasons');
select pg_temp.reject('update public.audit_events set action=''fake''','42501');
reset role;
select pg_temp.reject('update public.audit_events set action=''fake''','55000');
select pg_temp.reject('delete from public.session_corrections where id='''||current_setting('op.correction')||'''','55000');
select pg_temp.reject('update public.session_student_records set homework_status=''done'' where id='''||current_setting('op.record')||'''','55000');
update public.profiles set active=false where id='10000000-0000-0000-0000-000000000002';
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000002';
select pg_temp.assert_true((select count(*)=0 from public.notifications),'Inactive inbox fails closed');
select pg_temp.reject('select public.open_pilot_checkout('''||current_setting('op.session')||''',''mobile'')','42501');
reset role;
update public.profiles set active=true where id='10000000-0000-0000-0000-000000000002';
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000006';
select pg_temp.assert_true((select count(*)=0 from public.effective_session_records),'Media cannot read effective academic data');
select pg_temp.assert_true((select count(*)=0 from public.pilot_events),'Media cannot read analytics');
select pg_temp.reject('select public.run_daily_operations()','42501');
select pg_temp.reject('select public.run_scheduled_operations()','42501');
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000001';
select pg_temp.reject('select public.save_schedule(''20000000-0000-0000-0000-000000000002'',''10000000-0000-0000-0000-000000000003'',current_date+1,current_date+8,array[1],''17:00'',''18:00'')','42501');
select public.configure_pilot(false,'10000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000002',false);
select set_config('op.nonpilot',public.save_schedule('20000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000003',current_date+1,current_date+8,array[1],'17:00','18:00')::text,true);
select public.configure_pilot(true,'10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000001',true);
select pg_temp.reject('select public.generate_schedule('''||current_setting('op.nonpilot')||''',current_date+1,current_date+8)','42501');
select set_config('op.template',public.save_schedule('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002',(now() at time zone 'Asia/Bangkok')::date+1,(now() at time zone 'Asia/Bangkok')::date+8,array[extract(dow from (now() at time zone 'Asia/Bangkok')::date+1)::int],'19:00','20:30')::text,true);
select pg_temp.assert_true((public.generate_schedule(current_setting('op.template')::uuid,(now() at time zone 'Asia/Bangkok')::date+1,(now() at time zone 'Asia/Bangkok')::date+8)->>'generated')::int=2,'Weekly recurrence generates exact dates');
select pg_temp.assert_true(not exists(select 1 from public.class_sessions where template_id=current_setting('op.template')::uuid and ((starts_at at time zone 'Asia/Bangkok')::time<>'19:00'::time or (starts_at at time zone 'UTC')::time<>'12:00'::time)),'Local schedule 19:00 persists as UTC 12:00');
select pg_temp.assert_true((public.generate_schedule(current_setting('op.template')::uuid,(now() at time zone 'Asia/Bangkok')::date+1,(now() at time zone 'Asia/Bangkok')::date+8)->>'generated')::int=0,'Schedule retry dedup');
select set_config('op.skip',(select id::text from public.class_sessions where template_id=current_setting('op.template')::uuid order by starts_at limit 1),true);
select public.session_exception(current_setting('op.skip')::uuid,0,true,null,'Teacher holiday');
select pg_temp.assert_true((public.generate_schedule(current_setting('op.template')::uuid,(now() at time zone 'Asia/Bangkok')::date+1,(now() at time zone 'Asia/Bangkok')::date+8)->>'generated')::int=0,'Skipped date never regenerated');
select set_config('op.replace',public.save_schedule('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002',(now() at time zone 'Asia/Bangkok')::date+4,(now() at time zone 'Asia/Bangkok')::date+8,array[extract(dow from (now() at time zone 'Asia/Bangkok')::date+1)::int],'19:00','20:00',current_setting('op.template')::uuid,0)::text,true);
select pg_temp.assert_true((select ends_on=(now() at time zone 'Asia/Bangkok')::date+3 and active from public.class_schedule_templates where id=current_setting('op.template')::uuid),'Replacement preserves old schedule until X');
select pg_temp.reject('select public.save_schedule(''20000000-0000-0000-0000-000000000001'',''10000000-0000-0000-0000-000000000002'',(now() at time zone ''Asia/Bangkok'')::date+4,(now() at time zone ''Asia/Bangkok'')::date+8,array[1],''19:00'',''20:00'','''||current_setting('op.template')||''',1)','40001');
select public.generate_schedule(current_setting('op.replace')::uuid,(now() at time zone 'Asia/Bangkok')::date+4,(now() at time zone 'Asia/Bangkok')::date+8);
select pg_temp.assert_true((select count(*)=3 from public.class_sessions),'Replacement reuses cancelled future identity without duplication');
select set_config('op.conflict',public.save_schedule('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002',(now() at time zone 'Asia/Bangkok')::date+4,(now() at time zone 'Asia/Bangkok')::date+8,array[extract(dow from (now() at time zone 'Asia/Bangkok')::date+1)::int],'19:00','20:00')::text,true);
select pg_temp.assert_true(jsonb_array_length(public.generate_schedule(current_setting('op.conflict')::uuid,(now() at time zone 'Asia/Bangkok')::date+4,(now() at time zone 'Asia/Bangkok')::date+8)->'conflicts')=1,'Different templates same class/start warn conflict');
select pg_temp.reject('select public.session_exception('''||current_setting('op.session')||''',2,true,null,''Try completed mutation'')');
select pg_temp.reject('select public.generate_schedule('''||current_setting('op.replace')||''',null,null)');
insert into public.teacher_class_assignments(teacher_id,class_id) values('10000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000001');
select set_config('op.substitute',public.create_class_session('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002',((now() at time zone 'Asia/Bangkok')::date+20+time '15:00') at time zone 'Asia/Bangkok',((now() at time zone 'Asia/Bangkok')::date+20+time '15:30') at time zone 'Asia/Bangkok','Substitute fixture')::text,true);
select pg_temp.reject('select public.session_exception('''||current_setting('op.substitute')||''',0,false,''10000000-0000-0000-0000-000000000006'',''Invalid substitute teacher'')');
select public.session_exception(current_setting('op.substitute')::uuid,0,false,'10000000-0000-0000-0000-000000000003','Assigned substitute teacher');
select pg_temp.assert_true((select teacher_id='10000000-0000-0000-0000-000000000003' and version=1 and exception_reason='Assigned substitute teacher' from public.class_sessions where id=current_setting('op.substitute')::uuid),'Valid substitute is versioned and scoped to the session');
select pg_temp.reject('select public.session_exception('''||current_setting('op.substitute')||''',0,true,null,''Stale cancellation retry'')');
select public.create_class_session('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002',now()-interval '26 hours',now()-interval '25 hours','Overdue checkout');
reset role;
insert into public.tasks(student_id,type,owner_id,priority,title,due_at,created_at,created_by) values('30000000-0000-0000-0000-000000000001','general_attention','10000000-0000-0000-0000-000000000004','high','Overdue fixture',now()-interval '72 hours',now()-interval '10 hours','10000000-0000-0000-0000-000000000001');
-- Clock-injected engine is private, deterministic and not callable by API users.
select private.run_operations(now()+interval '72 hours');
select set_config('op.notices',(select count(*)::text from public.notifications),true);
select private.run_operations(now()+interval '72 hours');
select pg_temp.assert_true((select count(*)::text=current_setting('op.notices') from public.notifications),'Escalation retry dedup');
select pg_temp.assert_true(exists(select 1 from public.notifications where type='checkout_due' and user_id='10000000-0000-0000-0000-000000000002'),'Escalation teacher target');
select pg_temp.assert_true(exists(select 1 from public.notifications where type='task_overdue' and user_id='10000000-0000-0000-0000-000000000001'),'48h task escalates admin');
select set_config('op.foreign_notice',(select id::text from public.notifications where user_id='10000000-0000-0000-0000-000000000002' limit 1),true);
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000005';
select pg_temp.assert_true((select count(*)=0 from public.notifications),'User B cannot read A inbox');
select pg_temp.reject('select public.mark_notification('''||current_setting('op.foreign_notice')||''')','42501');
reset role;
set local role service_role;
select pg_temp.reject('update public.pilot_config set pilot_mode=false','42501');
select pg_temp.reject('delete from public.audit_events','42501');
rollback;
select 'Phase3 corrections/schedules/notifications/pilot/RLS PASS' result;
